package tv.stationbreak.core.engine.audit

/**
 * Stress libraries (#790): far bigger and stranger than any one household's, to show the lineup audit, and so the
 * planner and curation it runs, finish on them. Like the profile libraries they are generated by code from invented
 * titles; unlike them they are built at test time and have no golden output, because they are large and only their
 * completion and time are under test. Nothing in them is, or is meant to resemble, a real person's library.
 *
 * Two sizes of the broad library (10,000 and 25,000 titles), and six shapes of [SHAPE_TITLES] titles each: one series
 * with thousands of episodes, every title in one genre, titles with no genres, tags or studios, very large collections,
 * many near-identical titles, and extreme runtimes.
 */
@Suppress("MagicNumber") // The shape of a library is its data: counts, minutes and years are written as numbers.
internal object StressLibraries {
    const val SHAPE_TITLES = 10_000

    val keys: List<String> =
        listOf(
            "stress-broad-10000",
            "stress-broad-25000",
            "stress-long-series",
            "stress-one-genre",
            "stress-no-facts",
            "stress-big-collections",
            "stress-near-identical",
            "stress-extreme-runtimes",
        )

    fun build(key: String): Profile =
        when (key) {
            "stress-broad-10000" -> BroadLibrary.build(10_000)
            "stress-broad-25000" -> BroadLibrary.build(25_000)
            "stress-long-series" -> longSeries()
            "stress-one-genre" -> oneGenre()
            "stress-no-facts" -> noFacts()
            "stress-big-collections" -> bigCollections()
            "stress-near-identical" -> nearIdentical()
            "stress-extreme-runtimes" -> extremeRuntimes()
            else -> throw IllegalArgumentException("Not a stress library: ${key.length} characters")
        }

    private val RATINGS = listOf("PG", "PG-13", "R", "TV-14", "TV-MA", "G")

    private fun rating(i: Int) = RATINGS[i % RATINGS.size]

    private fun profile(
        key: String,
        description: String,
        b: LibraryBuilder,
    ) = Profile(key, description, AuditInput(b.build(), null), emptyList())

    // One drama with 5,000 episodes (50 seasons of 100), and films to make up the rest.
    private fun longSeries(): Profile {
        val b = LibraryBuilder(STRESS_LIBRARY)
        b.series(TitleSpec(listOf("Drama"), rating = "TV-14", minutes = 44), seasons = 50, episodes = 100)
        fillFilms(b, SHAPE_TITLES) { i -> TitleSpec(listOf("Comedy"), rating = rating(i), minutes = 95) }
        return profile("stress-long-series", "One series of 5,000 episodes beside $SHAPE_TITLES titles", b)
    }

    // Every title is a comedy, films and series alike.
    private fun oneGenre(): Profile {
        val b = LibraryBuilder(STRESS_LIBRARY)
        for (i in 0 until SHAPE_TITLES) {
            val spec = TitleSpec(listOf("Comedy"), rating = rating(i), minutes = 90 + i % 30, year = 1950 + i % 75)
            if (i % 5 == 0) b.series(spec.copyMinutes(22), seasons = 1 + i % 3, episodes = 8) else b.film(spec)
        }
        return profile("stress-one-genre", "$SHAPE_TITLES titles, every one a comedy", b)
    }

    // No genres, tags or studios on anything: nothing a recipe matches but ratings, years and runtimes.
    private fun noFacts(): Profile {
        val b = LibraryBuilder(STRESS_LIBRARY)
        for (i in 0 until SHAPE_TITLES) {
            val spec = TitleSpec(emptyList(), rating = rating(i), minutes = 30 + i % 120, year = 1940 + i % 85)
            if (i % 4 == 0) b.series(spec, seasons = 1, episodes = 6) else b.film(spec)
        }
        return profile("stress-no-facts", "$SHAPE_TITLES titles with no genres, tags or studios", b)
    }

    // The broad library's shelves, with five collections of 2,000 titles each over them.
    private fun bigCollections(): Profile {
        val base = BroadLibrary.builder(SHAPE_TITLES)
        val names = base.titleIds.keys.toList()
        for (c in 0 until 5) {
            val members = names.subList(c * 2_000, (c + 1) * 2_000)
            base.collection(if (c % 2 == 0) "${names[c]} Collection" else "${names[c]} picks", members)
        }
        return profile("stress-big-collections", "$SHAPE_TITLES titles in five collections of 2,000", base)
    }

    // The same facts on every title, and names that differ only by their number.
    private fun nearIdentical(): Profile {
        val b = LibraryBuilder(STRESS_LIBRARY)
        val stem = InventedNames().next()
        val spec = TitleSpec(listOf("Drama"), rating = "PG-13", minutes = 100, year = 1990)
        for (i in 2..SHAPE_TITLES + 1) b.film(spec, "$stem $i")
        return profile("stress-near-identical", "$SHAPE_TITLES titles with the same facts and near-identical names", b)
    }

    // Films of one minute and of fifteen hours, and series of one-minute episodes.
    private fun extremeRuntimes(): Profile {
        val b = LibraryBuilder(STRESS_LIBRARY)
        for (i in 0 until SHAPE_TITLES) {
            val minutes = if (i % 2 == 0) 1 else 900
            val genre = if (i % 2 == 0) "Drama" else "Comedy"
            val spec = TitleSpec(listOf(genre), rating = rating(i), minutes = minutes)
            if (i % 10 == 0) b.series(spec.copyMinutes(1), seasons = 1, episodes = 12) else b.film(spec)
        }
        return profile("stress-extreme-runtimes", "$SHAPE_TITLES titles of one minute or fifteen hours", b)
    }

    private fun fillFilms(
        b: LibraryBuilder,
        total: Int,
        spec: (Int) -> TitleSpec,
    ) {
        var i = 0
        while (b.titleIds.size < total) b.film(spec(i++))
    }

    private fun TitleSpec.copyMinutes(minutes: Int) = TitleSpec(genres, tags, studios, rating, minutes, year)

    private const val STRESS_LIBRARY = 7
}
